{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pirfenidone, the highest-similarity analogue, is rapidly absorbed and displays high oral bioavailability in humans and nonclinical species, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Edaravone, a pyrazolone sharing the N-phenyl/methyl/carbonyl core with the query, has an absolute oral bioavailability of 57.3% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Roquinimex, an N-phenyl/N-methyl heterocyclic drug, is modeled with complete oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Clobazam, a lipophilic N-phenyl heterocycle, has approximately 87% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Meperidine, a small lipophilic drug subject to first-pass metabolism, still has about 50% oral bioavailability, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Laquinimod, structurally related to roquinimex, has high oral bioavailability of approximately 80–90% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is aminopyrine, a small pyrazolone. The closest structural analogue edaravone has absolute oral bioavailability ~57% in humans, and multiple other related heterocyclic drugs show high oral bioavailability. The only low-bioavailability analogue, rutaecarpine, is structurally distant and does not transfer. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for aminopyrine itself is provided; the prediction relies on close analogues.",
    "One edaravone record describes the oral suspension as having poor bioavailability, but this is outweighed by multiple direct absolute F measurements of ~57%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

